const uid=()=>crypto.randomBytes(24).toString('base64url');
const shuffle=items=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=crypto.randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
const presentation=stage=>{const qs=questionsFor(stage);return{questions:shuffle(qs.map(q=>q.id)),options:Object.fromEntries(qs.filter(q=>q.options).map(q=>[q.id,shuffle(q.options.map((_,i)=>i))]))};};
const response=(res,status,data)=>res.status(status).json(data);
const error=(status,message)=>Object.assign(new Error(message),{status});
const body=req=>{const b=typeof req.body==='string'?JSON.parse(req.body||'{}'):req.body||{};if(JSON.stringify(b).length>80000)throw error(413,'Data terlalu besar');return b;};
