const secret=()=>{if(!process.env.ADMIN_SECRET)throw error(503,'ADMIN_SECRET belum terpasang');return process.env.ADMIN_SECRET;};
const sign=s=>crypto.createHmac('sha256',secret()).update(s).digest('base64url');
const equal=(a,b)=>{const x=Buffer.from(String(a)),y=Buffer.from(String(b));return x.length===y.length&&crypto.timingSafeEqual(x,y);};
const cookie=req=>String(req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('ansena_admin='))?.slice(13);
function isAdmin(req){try{const c=cookie(req);if(!c)return false;const [v,s]=c.split('.');if(v==='ok')return equal(s,crypto.createHmac('sha256',secret()).update('ok').digest('hex'));const exp=Number(v);return exp>Date.now()&&equal(s,sign(v));}catch{return false;}}
function admin(req){if(!isAdmin(req))throw error(401,'Silakan login admin');}
const keyMaterial=()=>crypto.createHash('sha256').update(secret()).digest();
function encrypt(value){const iv=crypto.randomBytes(12);const c=crypto.createCipheriv('aes-256-gcm',keyMaterial(),iv);const v=Buffer.concat([c.update(value,'utf8'),c.final()]);return[iv,c.getAuthTag(),v].map(x=>x.toString('base64')).join('.');}
function decrypt(value){const[iv,tag,v]=value.split('.').map(x=>Buffer.from(x,'base64'));const d=crypto.createDecipheriv('aes-256-gcm',keyMaterial(),iv);d.setAuthTag(tag);return Buffer.concat([d.update(v),d.final()]).toString('utf8');}
async function operations(){return{materialsHeld:true,comparisonEnabled:false,selfServeMaterials:false,postTestsLocked:true,...((await read('settings/v3-operations.json'))?.value||{})};}
async function aiConfig(){const settings=(await read('settings/v2-ai.json'))?.value||{};return{key:process.env.OPENAI_API_KEY||(settings.encryptedKey?decrypt(settings.encryptedKey):''),model:process.env.ASSESSMENT_AI_MODEL||settings.model||DEFAULT_GRADING_MODEL};}
const pendingWarning=s=>s.securityEvents.find(e=>e.kind==='warning'&&!e.confirmedAt&&e.deadlineAt);
function postExpiryDue(r,now=Date.now()){return Object.entries(r.stages).some(([stage,s])=>stage.startsWith('post:')&&s.status==='active'&&Number.isFinite(s.expiresAt)&&now>=s.expiresAt);}
function settlePostExpiry(r,now=Date.now()){for(const [stage,s] of Object.entries(r.stages)){if(!stage.startsWith('post:')||s.status!=='active'||!Number.isFinite(s.expiresAt)||now<s.expiresAt)continue;s.status='terminated';s.submittedAt=s.expiresAt;s.terminationReason='time_expired';s.result=aggregate(stage,s.answers,[],s.questionBankVersion||'legacy');s.grading={status:s.result.complete?'complete':'pending'};s.reviewRequired=true;s.securityEvents.push({type:'time_expired',at:s.expiresAt});}}
function securityDue(r,now=Date.now()){return Object.values(r.stages).some(s=>s.status==='active'&&pendingWarning(s)?.deadlineAt<=now);}
function settleSecurity(r,now=Date.now()){for(const [stage,s] of Object.entries(r.stages)){const warning=pendingWarning(s);if(s.status!=='active'||!warning||now<warning.deadlineAt)continue;s.status='submitted';s.submittedAt=warning.deadlineAt;s.autoSubmitReason='security_confirmation_timeout';s.result=aggregate(stage,s.answers,[],s.questionBankVersion||'legacy');s.grading={status:s.result.complete?'complete':'pending'};s.reviewRequired=true;warning.timedOutAt=warning.deadlineAt;}}
async function record(t,now=Date.now()){const r=await read(path(t));if(!r)throw error(404,'Undangan tidak ditemukan. Undangan versi lama perlu dibuat ulang oleh admin.');if(securityDue(r.value,now)||postExpiryDue(r.value,now)){await mutate(path(t),r=>{settlePostExpiry(r,now);settleSecurity(r,now);});return(await read(path(t))).value;}return r.value;}
function allowed(r,stage){if(!questionsFor(stage))throw error(400,'Tahap tidak valid');if(stage==='pre'||stage==='comparison')return;if(stage==='leadership'){if(!r.leaderTrack?.enabled)throw error(403,'Modul leader hanya untuk pelamar yang ditandai admin');if(!comparisonReady(r))throw error(409,'Selesaikan 10 soal umum dan penilaiannya dahulu');return;}const[kind,role]=stage.split(':');if(kind==='practical')throw error(409,'Practical dilakukan di luar web.');if(!postLeadershipReady(r)||!baselineReady(r)||!selectedMaterials(r).includes(role))throw error(409,'Materi dan post-test menunggu pilihan admin');if(!r.postTestAccess?.enabled&&!r.stages[stage])throw error(409,'Post-test belum dibuka oleh admin');if(!r.materialRead?.[role]&&!prePostClosed())throw error(409,'Baca materi sebelum post-test');}
function active(r,stage){const s=r.stages[stage];if(!s||s.status!=='active')throw error(409,'Tes tidak aktif');if(stage.startsWith('post:')&&Number.isFinite(s.expiresAt)&&Date.now()>=s.expiresAt)throw error(410,'Waktu tes habis');return s;}
function enforceLockedAnswers(s,answers){for(const[k,a]of Object.entries(s.lockedAnswers||{}))if(answers[k]!==a)throw error(409,'Jawaban yang telah tersimpan sebelum pemulihan tidak dapat diubah');}
function cleanProfile(p){const allowed=['interests','talents','education','reading','hobbies','learningInterests','mbti','zodiac','rolePreferences','english'];const out={};for(const k of allowed){if(p[k]!==undefined){if(typeof p[k]!=='string'||p[k].length>2000)throw error(400,'Profil tidak valid');out[k]=p[k].trim();}}return out;}
async function evaluate(token,stage){
 await record(token);
 const p=path(token);let snapshot;const jobId=uid();
 await mutate(p,r=>{allowed(r,stage);const s=r.stages[stage];if(!s||!['submitted','terminated'].includes(s.status))throw error(409,'Jawaban belum dikirim');if(s.grading?.status==='complete'){snapshot=null;return;}
 if(s.grading?.status==='running'&&s.grading.expiresAt>Date.now())throw error(409,'Penilaian sedang berjalan');s.grading={status:'running',jobId,expiresAt:Date.now()+80000};snapshot=structuredClone(s);});
 if(!snapshot)return{ok:true};
 try{const cfg=await aiConfig();const evaluated=await gradeEssays(stage,snapshot.answers,cfg.key,cfg.model,undefined,snapshot.questionBankVersion||'legacy');const result=aggregate(stage,snapshot.answers,evaluated.grades,snapshot.questionBankVersion||'legacy');
 await mutate(p,r=>{const s=r.stages[stage];if(s.grading?.jobId!==jobId)throw error(409,'Penilaian sudah diperbarui');s.grades=evaluated.grades;s.result=result;s.grading={...evaluated,status:'complete',grades:undefined};s.reviewRequired=evaluated.reviewRequired||s.status==='terminated'||s.securityEvents.some(e=>e.kind==='warning');});return{ok:true};
 }catch(e){await mutate(p,r=>{const s=r.stages[stage];if(s.grading?.jobId===jobId)s.grading={status:e.code==='AI_NOT_CONFIGURED'?'not_configured':'failed',error:e.code||'AI_REVIEW_REQUIRED',updatedAt:Date.now()};});throw error(e.code==='AI_NOT_CONFIGURED'?503:502,e.message);}
}
